mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.z += time * 1.5;
  vec2 id = floor(q.xz / 0.8);
  q.xz = mod(q.xz, 0.8) - 0.4;
  float chipH = 0.2 + 0.3 * sin(id.x * 2.0 + id.y * 3.0);
  vec3 b = abs(q) - vec3(0.32, chipH, 0.32);
  float chip = max(b.x, max(b.y, b.z));
  float fl = p.y + 0.2;
  return min(chip, fl);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 1.8, -2.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.5) * rd.yz;
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.01, 0.03, 0.05);
  if (t < 12.0) {
    vec3 pos = ro + rd * t;
    float trace = step(0.85, sin(pos.x * 20.0) * sin((pos.z + time * 1.5) * 20.0));
    float fog = 1.0 / (1.0 + t * t * 0.04);
    col = (vec3(0.05, 0.08, 0.12) + trace * vec3(0.0, 1.0, 0.8) * 2.2) * fog;
  }
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
